def is_strong(pw, personal):
    if len(pw) < 8:
        return False
    if not any(c.isdigit() for c in pw): return False
    if not any(c.isupper() for c in pw): return False
    if not any(c.islower() for c in pw): return False
    if not any(not c.isalnum() for c in pw): return False
    low = pw.lower()
    for w in personal + ['password', '123456']:
        if w.lower() in low:
            return False
    return True

