pr.solution:
def encrypt(text, k):
    out = ''
    for ch in text:
        if ch.isupper():
            out += chr((ord(ch) - 65 + k) % 26 + 65)
        elif ch.islower():
            out += chr((ord(ch) - 97 + k) % 26 + 97)
        else:
            out += ch
    return out

def decrypt(text, k):
    return encrypt(text, -k)

